use kni_guide_binding::*;
fn scope()->Scope { Scope{font:"font".into(),master:"master".into(),style:"style".into(),frame:"y-up".into()} }
fn pin()->String {"a".repeat(64)}
fn edge(id:&str,glyph:&str,class:&str,ys:&[f64])->EdgeObservation {EdgeObservation{edge_id:id.into(),glyph:glyph.into(),class:class.into(),source_pin:pin(),membership_evidence:"source-class-record".into(),source_y:ys.into()}}
fn image()->SpreadLimit {SpreadLimit::Image{font_units_per_source_pixel:2.0}}
fn inv(es:Vec<EdgeObservation>,cs:&[&str])->Inventory {derive(scope(),pin(),&cs.iter().map(|c|c.to_string()).collect::<Vec<_>>(),&es,image()).unwrap()}
fn node(id:&str,glyph:&str,y:f64,e:Option<&str>)->NodeObservation {NodeObservation{node_id:id.into(),scope:scope(),glyph:glyph.into(),y,source_edge_id:e.map(str::to_string)}}
#[test] fn source_median_and_signed_offsets_no_mutation(){
 let i=inv(vec![edge("e1","H","cap",&[100.0,101.0]),edge("e2","E","cap",&[101.0,102.0])],&["cap"]);
 assert_eq!(i.guides["cap"].y,Some(101.0));
 let ns=vec![node("n1","H",99.0,Some("e1")),node("n2","E",104.0,Some("e2"))];
 let before=ns.iter().map(|n|n.y.to_bits()).collect::<Vec<_>>();let rs=annotate(&i,&ns,BindingMode::Measure);
 assert_eq!(rs[0].signed_offset,Some(-2.0));assert_eq!(rs[1].signed_offset,Some(3.0));
 assert_eq!(before,ns.iter().map(|n|n.y.to_bits()).collect::<Vec<_>>());assert!(rs.iter().all(|r|r.mode==MODE));
 let s=summarize(&i,&rs);assert_eq!(s[0].signed_median,Some(0.5));assert_eq!(s[0].signed_p90,Some(3.0));assert_eq!(s[0].absolute_max,Some(3.0));
}
#[test] fn opt_in_and_missing_bindings_abstain(){let i=inv(vec![edge("a","H","cap",&[20.0]),edge("b","E","cap",&[20.0])],&["cap"]);let ns=vec![node("n","H",20.0,None)];assert_eq!(annotate(&i,&ns,BindingMode::default())[0].reason,Some("binding disabled"));let r=annotate(&i,&ns,BindingMode::Measure);assert_eq!(r[0].signed_offset,None);assert_eq!(r[0].reason,Some("missing source edge membership"));}
#[test] fn singleton_and_missing_classes_not_zero(){let i=inv(vec![edge("a","H","cap",&[20.0]),edge("b","H","cap",&[20.0])],&["cap","base"]);assert_eq!(i.guides["cap"].y,None);assert_eq!(i.guides["base"].y,None);assert_eq!(i.guides["cap"].reference_glyphs,1);}
#[test] fn class_and_edge_spread_abstain(){let i=inv(vec![edge("a","H","cap",&[0.0]),edge("b","E","cap",&[3.0])],&["cap"]);assert_eq!(i.guides["cap"].reason,Some("source class spread exceeds limit"));let i=inv(vec![edge("a","H","cap",&[0.0,4.0]),edge("b","E","cap",&[2.0])],&["cap"]);assert_eq!(i.guides["cap"].reason,Some("source edge spread exceeds limit"));}
#[test] fn at_limit_is_allowed(){let i=inv(vec![edge("a","H","cap",&[0.0]),edge("b","E","cap",&[2.0])],&["cap"]);assert_eq!(i.guides["cap"].y,Some(1.0));}
#[test] fn frame_and_glyph_identity_prevent_wrong_binding(){let i=inv(vec![edge("a","H","cap",&[20.0]),edge("b","E","cap",&[20.0])],&["cap"]);let mut n=node("n","H",20.0,Some("a"));n.scope.style="other".into();assert_eq!(annotate(&i,&[n],BindingMode::Measure)[0].reason,Some("scope or frame mismatch"));assert_eq!(annotate(&i,&[node("n","E",20.0,Some("a"))],BindingMode::Measure)[0].reason,Some("source edge glyph mismatch"));}
#[test] fn overshoot_stays_separate_and_never_nearest(){let i=inv(vec![edge("a","H","cap",&[100.0]),edge("b","E","cap",&[100.0]),edge("c","O","cap_round",&[104.0]),edge("d","C","cap_round",&[104.0])],&["cap","cap_round"]);let rs=annotate(&i,&[node("n","O",100.0,Some("c"))],BindingMode::Measure);assert_eq!(rs[0].class.as_deref(),Some("cap_round"));assert_eq!(rs[0].signed_offset,Some(-4.0));}
#[test] fn determinism_under_permutation(){let es=vec![edge("a","H","cap",&[10.0,11.0]),edge("b","E","cap",&[12.0])];let a=inv(es.clone(),&["cap"]);let b=inv(es.into_iter().rev().collect(),&["cap"]);assert_eq!(a.guides["cap"].y,b.guides["cap"].y);assert_eq!(a.guides["cap"].source_spread,b.guides["cap"].source_spread);}
#[test] fn reject_nonfinite_duplicate_unscoped_inputs(){let classes=vec!["cap".into()];let a=edge("a","H","cap",&[10.0]);assert!(matches!(derive(scope(),pin(),&classes,&[a.clone(),a],image()),Err(Error::DuplicateEdge)));assert!(matches!(derive(scope(),pin(),&classes,&[edge("a","H","cap",&[f64::NAN])],image()),Err(Error::NonFinite)));assert!(matches!(derive(scope(),pin(),&classes,&[],SpreadLimit::Image{font_units_per_source_pixel:0.0}),Err(Error::InvalidLimit)));let mut s=scope();s.frame.clear();assert!(matches!(derive(s,pin(),&classes,&[],image()),Err(Error::InvalidScope)));}
#[test] fn vector_limit_must_be_identified_not_image_reused(){let cs=vec!["cap".into()];let es=vec![edge("a","H","cap",&[20.0]),edge("b","E","cap",&[20.0])];let lim=SpreadLimit::VectorMeasured{font_units:0.0,derivation:"exact source spread".into()};let i=derive(scope(),pin(),&cs,&es,lim).unwrap();assert_eq!(i.guides["cap"].y,Some(20.0));assert_eq!(i.limit.label(),"vector: source-derived limit");assert!(matches!(derive(scope(),pin(),&cs,&es,SpreadLimit::VectorDeclared{font_units:1.0,derivation:String::new()}),Err(Error::InvalidLimit)));}
#[test] fn invalid_node_and_duplicate_node_not_measured(){let i=inv(vec![edge("a","H","cap",&[20.0]),edge("b","E","cap",&[20.0])],&["cap"]);let n=node("n","H",20.0,Some("a"));assert!(annotate(&i,&[n.clone(),n],BindingMode::Measure).iter().all(|r|r.signed_offset.is_none()));let r=annotate(&i,&[node("x","H",f64::INFINITY,Some("a"))],BindingMode::Measure);assert_eq!(r[0].signed_offset,None);}
